     sections+=f'<section class="rp-twelve-step"><div class="container"><div class="kicker">{n:02} · {name}</div><h2 class="heading">{heading}</h2><div class="rp-step-photos {"single" if len(pictures)==1 else "pair"}">{visuals}</div><p class="rp-illustration">{caption}</p><div class="rp-step-copy"><p>{body}</p></div></div></section>'
