   form=f'''<section class="section booking-section" id="booking"><div class="container booking-grid"><div class="booking-copy"><div class="kicker">{name}</div><h2 class="heading">{t['book']}</h2><p>{t['contact']}</p><div class="rp-price">{prices[i]} · {t['price']}</div>{'<p>'+t['min']+'</p>' if i==3 else ''}</div><form class="booking-form rp-form" action="https://wa.me/212667772551" method="get" target="_blank"><label>{t['date']}<input type="date" id="tripDate" required></label><label>{t['guests']}<input type="number" id="tripGuests" min="{4 if i==3 else 1}" step="1" value="{4 if i==3 else 2}" required></label><input type="hidden" name="text" id="tripMessage"><button class="btn btn-gold" type="submit">{t['send']} ↗</button></form></div></section>'''
